import hashlib, json
from styxx.sworn import Manifest
sha = lambda b: hashlib.sha256(b).hexdigest()

def _wrap(pieces, meta):
    text = "".join(pieces); offs = []; pos = 0
    for p in pieces:
        n = len(p.encode("utf-8")); offs.append((pos, pos + n)); pos += n
    return text, [{"start": offs[i][0], "end": offs[i][1], "receipt": r, "kind": k}
                  for (i, r, k) in meta]

def _man(entries, rung="L2", authored=()):
    m = Manifest(harness="acme-harness", turn="t1",
                 minted_at="2026-09-05T00:00:00Z", rung=rung)
    m.authored_sha256 = list(authored)
    for rid, (data, kos, comp) in entries.items():
        m.add(rid, data, kos, complete=comp, captured_at="2026-09-05T00:00:00Z")
    return m.to_dict()

